// Generated by scripts/gen-queries.ts from db/queries; do not edit.
export const queries = {
  alerts: "-- Alert log. GET /alerts?from=&to=&severity=&acknowledged=\n-- @params from:timestamptz to:timestamptz severity:text acknowledged:boolean limit:int offset:int zone:text\n-- @returns alert_id, timestamp, alert_type, severity, confidence, message, node_id, tree_label, cluster_id, cluster_name, acknowledged, acknowledged_by_name, acknowledged_at, email_sent_at\nSELECT a.alert_id, a.\"timestamp\", a.alert_type, a.severity, a.confidence, a.message,\n       a.node_id, n.tree_label, a.cluster_id, c.name AS cluster_name,\n       a.acknowledged, u.name AS acknowledged_by_name, a.acknowledged_at, a.email_sent_at\nFROM alert_log a\nLEFT JOIN nodes n ON n.org_id = a.org_id AND n.node_id = a.node_id\nLEFT JOIN cluster_heads c ON c.org_id = a.org_id AND c.cluster_id = a.cluster_id\nLEFT JOIN users u ON u.user_id = a.acknowledged_by\nWHERE a.org_id = current_org_id()\n  AND a.\"timestamp\" >= $1 AND a.\"timestamp\" < $2\n  AND ($3::text IS NULL OR a.severity = $3)\n  AND ($4::boolean IS NULL OR a.acknowledged = $4)\n  AND ($7::text IS NULL OR COALESCE(n.farm_zone, c.farm_zone) = $7)\nORDER BY a.\"timestamp\" DESC, a.alert_id DESC\nLIMIT $5 OFFSET $6;\n",
  classification_history: "-- Classification results over a period. GET /classifications?from=&to=&node_id=&label=&min_conf=&sort=\n-- @params from:timestamptz to:timestamptz node_id:bigint label:text min_conf:real sort:text limit:int offset:int zone:text\n-- @returns node_id, lora_id, tree_label, timestamp, model_version, label, confidence, inference_ms, processed_at\n-- sort: time_desc (default) | confidence_desc\nSELECT c.node_id, n.lora_id, n.tree_label, c.\"timestamp\", c.model_version, c.label, c.confidence,\n       c.inference_ms, c.processed_at\nFROM classification_results c\nJOIN nodes n ON n.org_id = c.org_id AND n.node_id = c.node_id\nWHERE c.org_id = current_org_id()\n  AND c.\"timestamp\" >= $1 AND c.\"timestamp\" < $2\n  AND ($3::bigint IS NULL OR c.node_id = $3)\n  AND ($4::text IS NULL OR c.label = $4)\n  AND ($5::real IS NULL OR c.confidence >= $5)\n  AND ($9::text IS NULL OR n.farm_zone = $9)\nORDER BY\n  CASE WHEN $6 = 'confidence_desc' THEN c.confidence END DESC,\n  c.\"timestamp\" DESC, c.node_id\nLIMIT $7 OFFSET $8;\n",
  classification_latest: "-- Classification screen default: latest result per node. GET /classifications\n-- @params label:text min_conf:real sort:text limit:int offset:int zone:text\n-- @returns node_id, lora_id, tree_label, timestamp, model_version, label, confidence, status, total_count\n-- sort: confidence_desc (default) | confidence_asc | time_desc | tree_asc\nSELECT n.node_id, n.lora_id, n.tree_label, s.last_classified AS \"timestamp\",\n       s.last_model_version AS model_version, s.last_label AS label,\n       s.last_runs[1] AS confidence, s.status, count(*) OVER () AS total_count\nFROM nodes n\nJOIN node_status s ON s.org_id = n.org_id AND s.node_id = n.node_id\nWHERE n.org_id = current_org_id()\n  AND s.classified_runs > 0\n  AND ($6::text IS NULL OR n.farm_zone = $6)\n  AND ($1::text IS NULL OR s.last_label = $1)\n  AND ($2::real IS NULL OR s.last_runs[1] >= $2)\nORDER BY\n  CASE WHEN $3 = 'confidence_asc' THEN s.last_runs[1] END ASC,\n  CASE WHEN $3 = 'time_desc' THEN s.last_classified END DESC,\n  CASE WHEN $3 = 'tree_asc' THEN n.tree_label END ASC,\n  s.last_runs[1] DESC, n.node_id\nLIMIT $4 OFFSET $5;\n",
  cluster_health: "-- System health, cluster-head cards. GET /health/clusters. NULL fields mean \"no data yet\".\n-- @returns cluster_id, name, farm_zone, uplink_type, revoked, last_seen, uptime_s, rssi_dbm, sd_free_mb, buffered_count\nSELECT c.cluster_id, c.name, c.farm_zone, COALESCE(h.uplink_type, c.uplink_type) AS uplink_type,\n       c.revoked, h.\"timestamp\" AS last_seen, h.uptime_s, h.rssi_dbm, h.sd_free_mb, h.buffered_count\nFROM cluster_heads c\nLEFT JOIN LATERAL (\n  SELECT ch.* FROM cluster_health ch\n  WHERE ch.org_id = c.org_id AND ch.cluster_id = c.cluster_id\n  ORDER BY ch.\"timestamp\" DESC LIMIT 1\n) h ON true\nWHERE c.org_id = current_org_id()\nORDER BY c.name;\n",
  energy_node: "-- Acoustic energy for one node. GET /nodes/{node_id}/energy?from=&to=&bucket=\n-- @params node_id:bigint from:timestamptz to:timestamptz bucket:interval\n-- @returns bucket, avg_energy, avg_snr_db, measurements\nSELECT time_bucket($4, f.\"timestamp\") AS bucket,\n       avg(f.energy)::real AS avg_energy,\n       avg(f.snr_db)::real AS avg_snr_db,\n       count(*)::int       AS measurements\nFROM acoustic_features f\nWHERE f.org_id = current_org_id() AND f.node_id = $1\n  AND f.\"timestamp\" >= $2 AND f.\"timestamp\" < $3\nGROUP BY 1\nORDER BY 1;\n",
  energy_overview: "-- Overlay chart: healthy average vs suspected vs alert. GET /energy/overview?from=&to=&bucket=\n-- Trees are grouped by their CURRENT status, not their status at the time of the measurement.\n-- @params from:timestamptz to:timestamptz bucket:interval zone:text\n-- @returns bucket, status, avg_energy, nodes, measurements\n-- Aggregate first (index-only, so no MFCC is loaded), then attach status. MATERIALIZED stops the\n-- planner undoing this: it underestimates the status filter and would look up node by node.\nWITH per_node AS MATERIALIZED (\n  SELECT time_bucket($3, f.\"timestamp\") AS bucket, f.node_id,\n         sum(f.energy) AS energy_sum, count(*) AS measurements\n  FROM acoustic_features f\n  WHERE f.org_id = current_org_id()\n    AND ($4::text IS NULL OR f.node_id IN (\n      SELECT n.node_id FROM nodes n WHERE n.org_id = current_org_id() AND n.farm_zone = $4))\n    AND f.\"timestamp\" >= $1 AND f.\"timestamp\" < $2\n  GROUP BY 1, 2\n)\nSELECT p.bucket, s.status,\n       (sum(p.energy_sum) / sum(p.measurements))::real AS avg_energy,\n       count(*)::int AS nodes,\n       sum(p.measurements)::int AS measurements\nFROM per_node p\nJOIN node_status s ON s.node_id = p.node_id\nWHERE s.org_id = current_org_id()\n  AND s.status IN ('healthy', 'suspected', 'alert')\nGROUP BY 1, 2\nORDER BY 1, 2;\n",
  historical_records: "-- Historical records. GET /nodes/{node_id}/features?from=&to=[&include=mfcc], and the CSV export.\n-- node_id NULL means every node in the organization.\n-- @params node_id:bigint from:timestamptz to:timestamptz include_mfcc:boolean limit:int offset:int zone:text\n-- @returns node_id, lora_id, tree_label, timestamp, energy, snr_db, rssi_dbm, status, msg_id, received_at, ingested_at, label, confidence, model_version, mfcc\nSELECT f.node_id, n.lora_id, n.tree_label, f.\"timestamp\", f.energy, f.snr_db, f.rssi_dbm, f.status,\n       f.msg_id, f.received_at, f.ingested_at,\n       c.label, c.confidence, c.model_version,\n       CASE WHEN $4 THEN f.mfcc END AS mfcc\nFROM acoustic_features f\nJOIN nodes n ON n.org_id = f.org_id AND n.node_id = f.node_id\nLEFT JOIN LATERAL (\n  SELECT r.label, r.confidence, r.model_version FROM classification_results r\n  WHERE r.org_id = f.org_id AND r.node_id = f.node_id AND r.\"timestamp\" = f.\"timestamp\"\n  ORDER BY r.processed_at DESC LIMIT 1\n) c ON true\nWHERE f.org_id = current_org_id()\n  AND ($1::bigint IS NULL OR f.node_id = $1)\n  AND ($7::text IS NULL OR n.farm_zone = $7)\n  AND f.\"timestamp\" >= $2 AND f.\"timestamp\" < $3\nORDER BY f.\"timestamp\" DESC, f.node_id\nLIMIT $5 OFFSET $6;\n",
  history_summary: "-- Historical records side panel: how many records, how many positive.\n-- @params node_id:bigint from:timestamptz to:timestamptz zone:text\n-- @returns total_records, positive_detections\nSELECT count(*)::int AS total_records,\n       (SELECT count(*)::int FROM classification_results c\n         JOIN nodes n ON n.org_id = c.org_id AND n.node_id = c.node_id\n         WHERE c.org_id = current_org_id() AND c.label = 'infested'\n           AND ($1::bigint IS NULL OR c.node_id = $1)\n           AND c.\"timestamp\" >= $2 AND c.\"timestamp\" < $3\n           AND ($4::text IS NULL OR n.farm_zone = $4)) AS positive_detections\nFROM acoustic_features f\nJOIN nodes n ON n.org_id = f.org_id AND n.node_id = f.node_id\nWHERE f.org_id = current_org_id()\n  AND ($1::bigint IS NULL OR f.node_id = $1)\n  AND f.\"timestamp\" >= $2 AND f.\"timestamp\" < $3\n  AND ($4::text IS NULL OR n.farm_zone = $4);\n",
  map_clusters: "-- Sensor map cluster-head markers. GET /map (cluster heads half)\n-- @returns cluster_id, name, farm_zone, location_lat, location_lon, revoked, last_seen, node_count\nSELECT c.cluster_id, c.name, c.farm_zone, c.location_lat, c.location_lon, c.revoked,\n       h.\"timestamp\" AS last_seen,\n       (SELECT count(*)::int FROM nodes n\n         WHERE n.org_id = c.org_id AND n.cluster_id = c.cluster_id AND n.active) AS node_count\nFROM cluster_heads c\nLEFT JOIN LATERAL (\n  SELECT ch.\"timestamp\" FROM cluster_health ch\n  WHERE ch.org_id = c.org_id AND ch.cluster_id = c.cluster_id\n  ORDER BY ch.\"timestamp\" DESC LIMIT 1\n) h ON true\nWHERE c.org_id = current_org_id()\nORDER BY c.name;\n",
  map_nodes: "-- Sensor map markers. GET /map (nodes half). Deliberately not paginated: the map draws them all.\n-- @params zone:text\n-- @returns node_id, lora_id, tree_label, farm_zone, cluster_id, location_lat, location_lon, status, avg_confidence\nSELECT n.node_id, n.lora_id, n.tree_label, n.farm_zone, n.cluster_id,\n       n.location_lat, n.location_lon, s.status, s.avg_confidence\nFROM nodes n\nJOIN node_status s ON s.org_id = n.org_id AND s.node_id = n.node_id\nWHERE n.org_id = current_org_id()\n  AND n.location_lat IS NOT NULL AND n.location_lon IS NOT NULL\n  AND ($1::text IS NULL OR n.farm_zone = $1)\nORDER BY n.tree_label, n.node_id;\n",
  node_health: "-- System health, node cards. GET /health/nodes. NULL battery/uptime means \"no data yet\".\n-- @params limit:int offset:int zone:text\n-- @returns node_id, lora_id, tree_label, farm_zone, status, battery_mv, rssi_dbm, uptime_s, last_heartbeat, last_classified, total_count\nSELECT n.node_id, n.lora_id, n.tree_label, n.farm_zone, s.status, s.battery_mv, s.rssi_dbm,\n       s.uptime_s, s.last_heartbeat, s.last_classified,\n       count(*) OVER () AS total_count\nFROM nodes n\nJOIN node_status s ON s.org_id = n.org_id AND s.node_id = n.node_id\nWHERE n.org_id = current_org_id()\n  AND ($3::text IS NULL OR n.farm_zone = $3)\nORDER BY n.tree_label, n.node_id\nLIMIT $1 OFFSET $2;\n",
  organization: "-- The organization's own settings. GET /orgs/{org_id}\n-- @returns org_id, name, slug, timezone, suspect_threshold, alert_threshold\nSELECT o.org_id, o.name, o.slug, o.timezone, o.suspect_threshold, o.alert_threshold\nFROM organizations o\nWHERE o.org_id = current_org_id();\n",
  pipeline_latency: "-- Ingest -> classification and ingest -> alert latency, for report Table 6.3.\n-- @params from:timestamptz to:timestamptz\n-- @returns classified, classify_p50_ms, classify_p95_ms, alerts, alert_p50_ms, alert_p95_ms\nWITH classified AS (\n  SELECT EXTRACT(EPOCH FROM c.processed_at - f.ingested_at) * 1000 AS ms\n  FROM classification_results c\n  JOIN acoustic_features f ON f.node_id = c.node_id AND f.\"timestamp\" = c.\"timestamp\"\n  WHERE c.org_id = current_org_id() AND c.\"timestamp\" >= $1 AND c.\"timestamp\" < $2\n),\nalerted AS (\n  SELECT EXTRACT(EPOCH FROM a.created_at - f.ingested_at) * 1000 AS ms\n  FROM alert_log a\n  JOIN acoustic_features f ON f.node_id = a.node_id AND f.\"timestamp\" = a.measurement_ts\n  WHERE a.org_id = current_org_id() AND a.measurement_ts >= $1 AND a.measurement_ts < $2\n)\nSELECT (SELECT count(*)::int FROM classified) AS classified,\n       (SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY ms) FROM classified)::real AS classify_p50_ms,\n       (SELECT percentile_cont(0.95) WITHIN GROUP (ORDER BY ms) FROM classified)::real AS classify_p95_ms,\n       (SELECT count(*)::int FROM alerted) AS alerts,\n       (SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY ms) FROM alerted)::real AS alert_p50_ms,\n       (SELECT percentile_cont(0.95) WITHIN GROUP (ORDER BY ms) FROM alerted)::real AS alert_p95_ms;\n",
  summary_cards: "-- Overview stat cards. GET /summary?zone=\n-- @params zone:text\n-- @returns trees_monitored, healthy, suspected, alerts, offline, unknown, active_nodes, total_nodes, measurements_last_hour, suspected_yesterday, suspected_change, with_heartbeat\nWITH zone_nodes AS (\n  SELECT n.node_id FROM nodes n\n  WHERE n.org_id = current_org_id() AND n.active\n    AND ($1::text IS NULL OR n.farm_zone = $1)\n),\ncurrent_status AS (\n  SELECT s.status, s.last_heartbeat FROM node_status s\n  JOIN zone_nodes z ON z.node_id = s.node_id\n  WHERE s.org_id = current_org_id()\n),\nyesterday AS (\n  -- The same last-3 rule, as things stood 24 h ago.\n  SELECT count(*) FILTER (WHERE y.avg_confidence >= o.suspect_threshold\n                            AND y.avg_confidence < o.alert_threshold) AS suspected\n  FROM zone_nodes z\n  JOIN organizations o ON o.org_id = current_org_id()\n  CROSS JOIN LATERAL (\n    SELECT avg(l.confidence) AS avg_confidence FROM (\n      SELECT c.confidence FROM classification_results c\n      WHERE c.org_id = current_org_id() AND c.node_id = z.node_id\n        AND c.\"timestamp\" <= now() - INTERVAL '24 hours'\n      ORDER BY c.\"timestamp\" DESC LIMIT 3\n    ) l\n  ) y\n),\ncounts AS (\n  SELECT count(*)::int                                     AS trees_monitored,\n         count(*) FILTER (WHERE status = 'healthy')::int   AS healthy,\n         count(*) FILTER (WHERE status = 'suspected')::int AS suspected,\n         count(*) FILTER (WHERE status = 'alert')::int     AS alerts,\n         count(*) FILTER (WHERE status = 'offline')::int   AS offline,\n         count(*) FILTER (WHERE status = 'unknown')::int   AS unknown,\n         count(last_heartbeat)::int                        AS with_heartbeat\n  FROM current_status\n)\nSELECT c.trees_monitored, c.healthy, c.suspected, c.alerts, c.offline, c.unknown,\n       c.trees_monitored - c.offline AS active_nodes,\n       c.trees_monitored             AS total_nodes,\n       (SELECT count(*)::int FROM acoustic_features f\n         WHERE f.org_id = current_org_id() AND f.\"timestamp\" >= now() - INTERVAL '1 hour'\n           AND f.node_id IN (SELECT node_id FROM zone_nodes)) AS measurements_last_hour,\n       y.suspected::int              AS suspected_yesterday,\n       c.suspected - y.suspected::int AS suspected_change,\n       c.with_heartbeat\nFROM counts c, yesterday y;\n",
  tree_cards: "-- Overview tree cards. GET /trees?zone=&status=&q=\n-- @params zone:text status:text q:text limit:int offset:int\n-- @returns node_id, lora_id, tree_label, farm_zone, cluster_id, status, avg_confidence, last_runs, last_measurement, measurements_24h, battery_mv, rssi_dbm, location_lat, location_lon, total_count\n-- Filter and page first, so the per-card look into acoustic_features runs only for one page.\nWITH page AS (\n  SELECT n.node_id, n.org_id, n.lora_id, n.tree_label, n.farm_zone, n.cluster_id,\n         s.status, s.avg_confidence, s.last_runs, s.battery_mv, s.rssi_dbm,\n         n.location_lat, n.location_lon,\n         count(*) OVER () AS total_count\n  FROM node_status s\n  JOIN nodes n ON n.org_id = s.org_id AND n.node_id = s.node_id\n  WHERE s.org_id = current_org_id()\n    AND ($1::text IS NULL OR n.farm_zone = $1)\n    AND ($2::text IS NULL OR s.status = $2)\n    AND ($3::text IS NULL OR n.tree_label ILIKE '%' || $3 || '%' OR n.lora_id::text = $3)\n  ORDER BY n.tree_label, n.node_id\n  LIMIT $4 OFFSET $5\n)\nSELECT p.node_id, p.lora_id, p.tree_label, p.farm_zone, p.cluster_id,\n       p.status, p.avg_confidence, p.last_runs,\n       (SELECT f.\"timestamp\" FROM acoustic_features f\n         WHERE f.org_id = p.org_id AND f.node_id = p.node_id\n         ORDER BY f.\"timestamp\" DESC LIMIT 1) AS last_measurement,\n       (SELECT count(*)::int FROM acoustic_features f\n         WHERE f.org_id = p.org_id AND f.node_id = p.node_id\n           AND f.\"timestamp\" >= now() - INTERVAL '24 hours') AS measurements_24h,\n       p.battery_mv, p.rssi_dbm, p.location_lat, p.location_lon, p.total_count\nFROM page p\nORDER BY p.tree_label, p.node_id;\n",
  tree_detail: "-- One tree. GET /trees/{node_id}. No row (so 404) for another organization's node.\n-- @params node_id:bigint\n-- @returns node_id, lora_id, tree_label, farm_zone, cluster_id, cluster_name, install_date, location_lat, location_lon, status, avg_confidence, last_runs, last_classified, last_heartbeat, battery_mv, rssi_dbm, uptime_s\nSELECT n.node_id, n.lora_id, n.tree_label, n.farm_zone, n.cluster_id, c.name AS cluster_name,\n       n.install_date, n.location_lat, n.location_lon,\n       s.status, s.avg_confidence, s.last_runs, s.last_classified,\n       s.last_heartbeat, s.battery_mv, s.rssi_dbm, s.uptime_s\nFROM nodes n\nJOIN cluster_heads c ON c.org_id = n.org_id AND c.cluster_id = n.cluster_id\nJOIN node_status s ON s.org_id = n.org_id AND s.node_id = n.node_id\nWHERE n.org_id = current_org_id() AND n.node_id = $1;\n",
  zones: "-- The zone selector in the top bar. GET /zones\n-- @returns farm_zone, trees\nSELECT n.farm_zone, count(*)::int AS trees\nFROM nodes n\nWHERE n.org_id = current_org_id() AND n.active AND n.farm_zone IS NOT NULL\nGROUP BY n.farm_zone\nORDER BY n.farm_zone;\n",
} as const;
